//! The embedded map palette (`data/colors.json`, generated by
//! `tools/color-gen` from the pinned client.jar) plus name resolution for
//! Bedrock worlds (Bedrock names → Java names through the converter's
//! derived inverse table, so one palette serves both editions).

use std::collections::{BTreeMap, HashMap};
use std::sync::{OnceLock, RwLock};

use omt_world::BlockState;

/// Which biome color multiplies a block's (grayscale) texture color.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Tint {
    None,
    Grass,
    Foliage,
    Water,
}

/// A block's map color: straight RGBA plus its biome tint class.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BlockColor {
    pub rgba: [u8; 4],
    pub tint: Tint,
}

impl BlockColor {
    pub const CLEAR: Self = Self { rgba: [0, 0, 0, 0], tint: Tint::None };
    /// Unknown (modded / future) blocks: neutral magenta-gray, opaque, so
    /// they stay visible on the map without pretending to be anything.
    pub const UNKNOWN: Self = Self { rgba: [150, 110, 150, 255], tint: Tint::None };

    pub fn is_clear(&self) -> bool {
        self.rgba[3] == 0
    }
}

/// Biome tint triple (0xRRGGBB).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BiomeColors {
    pub grass: u32,
    pub foliage: u32,
    pub water: u32,
}

impl BiomeColors {
    /// Plains — the fallback for unknown biomes.
    pub const DEFAULT: Self = Self { grass: 0x91bd59, foliage: 0x77ab2f, water: 0x3f76e4 };
}

pub struct Palette {
    blocks: HashMap<String, BlockColor>,
    biomes: HashMap<String, BiomeColors>,
    /// Bedrock numeric biome id → Java biome name.
    bedrock_biomes: BTreeMap<i32, String>,
    /// Memoized Bedrock-name → color for names absent from the Java table.
    resolved: RwLock<HashMap<String, BlockColor>>,
}

static EMBEDDED: OnceLock<Palette> = OnceLock::new();

impl Palette {
    /// The palette compiled into the binary.
    pub fn embedded() -> &'static Palette {
        EMBEDDED.get_or_init(|| {
            Self::from_json(include_str!("../data/colors.json")).expect("embedded colors.json is valid")
        })
    }

    pub fn from_json(text: &str) -> Result<Self, String> {
        let v: serde_json::Value = serde_json::from_str(text).map_err(|e| e.to_string())?;
        let mut blocks = HashMap::new();
        for (name, arr) in v["blocks"].as_object().ok_or("missing blocks")? {
            let a: Vec<u8> = arr
                .as_array()
                .ok_or("block entry not an array")?
                .iter()
                .map(|n| n.as_u64().unwrap_or(0) as u8)
                .collect();
            if a.len() != 5 {
                return Err(format!("bad entry for {name}"));
            }
            let tint = match a[4] {
                1 => Tint::Grass,
                2 => Tint::Foliage,
                3 => Tint::Water,
                _ => Tint::None,
            };
            blocks.insert(name.clone(), BlockColor { rgba: [a[0], a[1], a[2], a[3]], tint });
        }
        let mut biomes = HashMap::new();
        for (name, arr) in v["biomes"].as_object().ok_or("missing biomes")? {
            let c: Vec<u32> = arr.as_array().into_iter().flatten().map(|n| n.as_u64().unwrap_or(0) as u32).collect();
            if c.len() == 3 {
                biomes.insert(name.clone(), BiomeColors { grass: c[0], foliage: c[1], water: c[2] });
            }
        }
        let bedrock_biomes = omt_convert::RegistryRules::embedded().biome_names();
        Ok(Self { blocks, biomes, bedrock_biomes, resolved: RwLock::new(HashMap::new()) })
    }

    /// Every known biome name, sorted (editor suggestions).
    pub fn biome_names(&self) -> Vec<&str> {
        let mut v: Vec<&str> = self.biomes.keys().map(String::as_str).collect();
        v.sort_unstable();
        v
    }

    /// Every known block name, sorted (editor suggestions).
    pub fn block_names(&self) -> Vec<&str> {
        let mut v: Vec<&str> = self.blocks.keys().map(String::as_str).collect();
        v.sort_unstable();
        v
    }

    /// Map color of a block by name (default state).
    pub fn color_of(&self, name: &str) -> [u8; 4] {
        self.blocks.get(name).map_or([0x80, 0x80, 0x80, 255], |c| c.rgba)
    }

    pub fn block_count(&self) -> usize {
        self.blocks.len()
    }

    /// Color for a block state of either edition.
    pub fn block(&self, state: &BlockState) -> BlockColor {
        if let Some(c) = self.blocks.get(&state.name) {
            return *c;
        }
        // Read-mostly memo (render threads hit it per palette entry).
        if let Some(c) = self.resolved.read().expect("palette cache poisoned").get(&state.name) {
            return *c;
        }
        let c = self.bedrock_fallback(state);
        self.resolved.write().expect("palette cache poisoned").insert(state.name.clone(), c);
        c
    }

    /// Bedrock names that differ from Java go through the converter's
    /// derived inverse; anything still unknown renders as [`BlockColor::UNKNOWN`].
    fn bedrock_fallback(&self, state: &BlockState) -> BlockColor {
        let reverse = reverse_rules();
        let mut reported = std::collections::BTreeSet::new();
        let mut report = omt_convert::ConversionReport::default();
        let mapped = reverse.map_block(state, &mut reported, &mut report);
        self.blocks.get(&mapped.state.name).copied().unwrap_or(BlockColor::UNKNOWN)
    }

    pub fn biome(&self, java_name: &str) -> BiomeColors {
        self.biomes.get(java_name).copied().unwrap_or(BiomeColors::DEFAULT)
    }

    /// Java biome name for a Bedrock numeric biome id.
    pub fn bedrock_biome_name(&self, id: i32) -> Option<&str> {
        self.bedrock_biomes.get(&id).map(String::as_str)
    }
}

fn reverse_rules() -> &'static omt_convert::rules::ReverseBlockRules {
    static REV: OnceLock<omt_convert::rules::ReverseBlockRules> = OnceLock::new();
    REV.get_or_init(|| omt_convert::RegistryRules::embedded().reverse())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn st(name: &str) -> BlockState {
        BlockState { name: name.into(), properties: vec![] }
    }

    #[test]
    fn embedded_palette_shape() {
        let p = Palette::embedded();
        assert!(p.block_count() > 1200, "full vanilla block set");
        assert!(p.block(&st("minecraft:air")).is_clear());
        assert_eq!(p.block(&st("minecraft:grass_block")).tint, Tint::Grass);
        assert_eq!(p.block(&st("minecraft:oak_leaves")).tint, Tint::Foliage);
        assert_eq!(p.block(&st("minecraft:water")).tint, Tint::Water);
        assert_eq!(p.block(&st("minecraft:stone")).rgba[3], 255);
        assert_eq!(p.biome("minecraft:plains").grass, 0x91bd59, "vanilla plains grass");
        assert_eq!(p.block(&st("mod:thing")), BlockColor::UNKNOWN);
    }
}
